WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (128::BIGINT, 'El curso es casi todo asincrónico, deja 1 trabajo cada semana y una investigación que se va desarrollando a lo largo del semestre. No es muy dificil pero si toma su tiempo cada trabajo, la mayoria de trabajos es en grupo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2026-07-09T00:00:00+00:00'::TIMESTAMPTZ, '23ef0161d7d09228158aec3f23ad6d886f683afad795245e7654db43a4679182'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Hay 10 tareas, 2 análisis de casos y una investigación que abarca a todo el semestre. No es lo más duro pero sí hay que dedicarle un poco de tiempito obvio. Pero es un profe muy llevadero.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e3f1ab9f0689011f55a2ee34005a1d61369e29d5ac60b7b9e8e0cd46a6d78b7d'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Muy buena opción para este tipo de cursos, casi todo es de forma asíncrona, y si te juntas con un grupo que si trabaje la carga de todos los trabajos ni se siente, muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-25T00:00:00+00:00'::TIMESTAMPTZ, '7f66b1381a0cc02b157b35ce1d9d4ffc391ff26b5be969e5f59dc505d58827f8'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'No se complique y meta con este profe. Casi todo es asíncrono, aunque algunas si hay que reunirse por zoom y hacer presentaciones simples. Bastante bien todo, y califica bastante bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1eed058a995bf734c9c0bf12bbae0976e19efa3f8dac960028143ac1217966a4'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'DEMASIADOS TRABAJOS. Pero es fácil y en general uno aprende que es el objetivo del curso, además es un curso interesante. El profe es bueno y los trabajos salen rápido en realidad. Es muy amigable entonces uno siente el ambiente de confianza con el. Buena opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'be0106ee086fadfef2f32321e278942e8f48ef466e64b0ea3abd42dc4e6cfa9f'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es de las mejores opciones para este curso, el profe es buena nota y califica bastante suave, a pesar de que hay bastantes trabajos por hacer. Definitivamente una excelente opción si tiene un semestre cargado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '63ff5145c1348ea015ab76892c462c63b7b315095a27df7fe3ca5ab474ebcf93'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Esta bien, es buena opción si no quiere complicarse'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b07b02afc9a99f528e7e443837c8a23e5f65408248e7e88bf23d6ccbed7b64a8'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Habla demasiado en clase, las clases las hace aburridas y cuando dice algo, lo hace para criticar ideologías y todo lo malo lo trata de "capitalismo", además casi todas las clases son dadas por presentaciones de estudiantes de la enorme cantidad de lecturas que pone'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2024-10-02T00:00:00+00:00'::TIMESTAMPTZ, '9d209e69459768be80db1d4fa7cc9ab248edd76127060cf257c90dfb759d7d88'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'A pesar de que los trabajos se vean largos, se pueden sacar en un rato. No califica duro, pero si estricto con las citas. Las clases son muy dinámicas, ayuda a que no se aburra más de lo que es el curso como tal.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'e738c96bf4d6e1554aa7f2206331cd992fac43c12b6727490be8ef83c7d7df47'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Este profe califica y deja trabajos como si su clase fuera la mas importante de la carrera, ej: esta va a dejar lecturas semanales y a mitad de semestre creara una guia con extencion minima de preguntar sobre estas guias y no son preguntar cortas, el hpt pide hasta ejemplos, con apa 7 perfecto'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'd784fc0392e7dca742fd6d6e638b8d0255da0d43dc6fd4f301d82a3998500ba7'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Buena nota este profe, super accesible y abierto a negociar, deja muchas lecturas pero tambien deja los powerpoints con la info importante entonces se pueden ignorar (Igual son textos cortos). Deja varios trabajos pero si sabe APA y redactar masomenos bien, pasa super facil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'dd26ad64a51cf65c2049631efa7c1889f38e7ff0cc178d6f352bfc643b0b3d3c'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Aunque uno deba de leer mucho y hacer varios trabajos, pasar con él es muy fácil. Sus clases son super cortas y entretenidas. Matricule con él si quiere pasar fácil la materia. Además, si vos quieres puedes no ir a la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'aac146afb726da6b5f17f3aef71836425ba59bd18cab78fbde42d8b1204bbc7d'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Clases muy dinámicas con Mentimeter / Jamboard, excelente actitud, muy analítico con comentarios valiosos, da solo 1h de clase, si no va no hay problema, las lecturas puede no hacerlas y pasa, trabajos sencillos siempre que justifique bien y use APA. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5121fb818a0788b3532f375696c737ed8b3243672db6adcbd488d4f2691526e5'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Es un buen profesor, si les gusta el tema de la clase, las hace muy interesantes. Sabe mucho y la participación en clase la hace bastante dinámica.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-04-22T00:00:00+00:00'::TIMESTAMPTZ, '54ee056c64691b3c826d56d7fd2ef7f686812e6b840a726dbff01f52f10ad46f'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'El es un gran profesor, en general es pura vida. Tienes que manejar bien APA debido a que lo toma mucho en cuenta a la hora de evaluar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Pocos exámenes']::TEXT[], '2023-02-07T00:00:00+00:00'::TIMESTAMPTZ, '4a9e647f5a6f869be13365205c76977e74e792642cbe36de2bb876515850c170'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Muy muy buen profe, eso sí muy muy importante saber bien el APA, a veces las clases son algo repetitivas pero no son largas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '44cec9a0232b0f8c09fd1bce07040c7629db55eb9e2a3eb52aad5f105bb727db'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Hagan lo que hagan no matriculen con el, califica de muy mala manera, no revisa bien lo informes ni se preocupa por verificar que estén bien, simplemente te pone una nota aleatoria, lo cual te puede llegar a afectar de forma negativa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5626c91817a83f4158fa61a5355f5af8ac3ad11e16fe9377721f3de184dd8338'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Es muy buen profesor, siempre esta dispuesto a ayudar, el "proyecto" es hacer una investigación y exponerla. Se debe saber manejar las normas APA, pues todos los trabajos son en ese formato. Explica bien, se aprende y se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'eec481d25616200df2eea19f2d52798d0e665d7332efff1f138926b9fd924554'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, '9d5d7890d44538291eb41e2d9902b35fc57bd021e42f612f774d0341c4b8e666'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'El curso, por más aburrido que sea, hace del mismo lo menos cansado posible, eso sí, todo es en grupo y hay algunas clases donde es uno quién la da y es sorpresa entonces hay que ir con todo leído y tienen que manejar APA al 100% y sepan investigar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'ee055f9ca0eeed7789a7ff48d650236dca5450c9e171649f515a9ac39b364f04'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Tenés que leer o ver algo antes de clase y siempre es llegar a hacer una presentación para luego presentarla y que el la comente. Todo es grupal y el escoge grupos, si usted puede hacer un grupo con gente conocida responsable , dígale, si no lo puede poner con irresponsables. Todo en APA.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9aca1b1c8359026bc5b64e268a0f9beb2916c4b40451f3618dd1311ea7f80aaa'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'El profe es buena gente y super conocedor de la materia. Pero se hace la misma dinámica todas las clases, hacer una presentacion en grupo y que él la comente. Tareas semanales y examenes en grupo y con apa. Es comprensivo si usted tiene alguna situación. El curso es fácil con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9012c84aecb892a4e784e4dd72ad57f587555c910945c9250732b7381333018e'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'El profesor sabe mucho y es buena persona, sin embargo a la hora de dar la clase no hace que se tenga interés en ella, ya que se vuelve muy monótona: siempre es llegar a hacer una presentación para luego presentarla y ya. Además, absolutamente TODAS las evaluaciones son grupales, hasta los examenes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '061111982ee9b7a2bd7f71e3885d62860bec99ea32bb0d1e305b31e86f99455f'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Excelente profesor. Enseña y se interesa. Virtual deja ensayos; 4 en total de 10% pero da tiempo y tal y se hace un proyecto final teniendo 1 primer avance y uno final. Excelente profesor para el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '0e48c3afafcec2c22f0f691bb0bf0fae6bca607889a489a2d855f9ef5459bc76'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es demasiado agradable e inteligente, sus clases dan gusto incluso virtuales. Deja trabajos continuamente como hacer ensayos a partir de documentales o películas pero siempre que usted cumpla el formato APA bien saca el curso como si nada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'de76f3068365b08ab6c1c6a454371babbef0d3e677e73d62a7dfd627300da1a5'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Súper fácil todo, es un curso que puede parecer tedioso pero es interesante y el profe lo vuelve poco pesado y poco cansado. Las tareas son como ver peliculas (que son super interesantes) y ensayos en grupo (cortos). Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'd40c034ea929a6e60b2a0de9c1171169a1664ca2e6d72b8bbc5b5ef6de33d3d2'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'El modalidad presencial el profe explicaba bien, de igual forma en modalidad virtual. Un poco cansado porque hay que hacer trabajos semanales, pero se saca rápido.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '2415bfcb20fa5d842315cce17f19c53cc4cf9c10ddcb0bd8ffd2bd52632fdb84'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Muy bueno, solo deja trabajos en ver de dar clases y el curso lo podes hacer todo en parejas o individual. Todas las semanas hay que entregar trabajos entonces hay que dedicar sus horas pero nada muy complicado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'a2048b5a39c266f3c1e1d3deb9b0c6bc3756710bc6f6300ed2971ee6946e95f3'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'En modalidad virtual trabajó completamente asincronico, el proyecto final fue un ensayo, todos los trabajos se pueden hacer en parejas, en general bastante bien. Lo único malo es que semanalmente se entrega un ensayo, no muy complicado pero si requiere varias horas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'f522fcdfeb119cb7ecebb1b0d1ba773c106c6b6ec247c98b923436387074bc21'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es bueno para la modalidad virtual, deja trabajos cortos cada semana en lugar de dar clases y califica normal'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '55999a4682b26d267d20b8f7c6dda5964ef692adc3f69cff8dc34a819835ec2f'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '055dea6136370ebd63a48bf66162f8f7bca4942932c4df461c03a045909c584b'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es bueno, sólo que a diferencia de otros profes deja bastantes trabajos, si los hace todos tiene 100 casi seguro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '465d7f35e1706d3866bc93e93b784134902bbfa2658b0efbfdf47f8decc248b9'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Las clases son entretenidas y se le entiende bastante bien. Todos los trabajos son grupales. Si entrega todos los trabajos tiene 100 casi asegurado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '078c84c89fb0ef67373d134136fcff4163ab54fe7bb8fc57cb6817d612e4ae13'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '9668ae04bbadabf880c42a6c604240f534255aef3bbe297caae8ebe1d7c59524'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Excelente profe. Las clases no son largas, le gusta hablar y dar su punto de vista. Los trabajos son bastantes pero son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '5c6b6341820b875fe995836fd7bd1cc74b667e65dd24541537a60b689fbd21b5'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Buen profe, el curso con él no es tan aburrido, es comprensivo con algunas situaciones, los trabajos de clase por lo general los deja para ser entregados un dia o dos despues de la clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '33c6f199b517c62da1625413bdae435070bbec58422b6d1e375c4798b78e871e'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Habla mucho pero es muy buena gente. El curso se presta para discusiones interesantes entre todo el grupo. Después de las exposiciones repite lo que uno dijo y se extienden un montón. Hay muchos trabajos pero son fáciles de hacer (si cumple eso de ser de 2 créditos).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8c6a69de47b72ca6cb3e7eac64ecda1d65a1c063895f84d30d65ee91dc23a5bf'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Excelente profe, habla bastante y se nota que sabe mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c942d9bafe9254bf12372d71be768b6c60381395c7f9a98159e99f3b3e5698f9'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Explica bien cuando tiene que explicar. Las clases no son tan aburridas. Habla demasiado, tanto que a veces es agobiante.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '30b4afdac96dd057deaf9188118a871c0538af6e3e7d985efe11937ccf472d32'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Excelente profe, la clases son interesantes siempre y cuando no haya exposiciones. La desventaja es que deja demasiados trabajos para un curso de 2 créditos. Si usted es aplicado, va a pasar el curso con muy buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '870d2bfa65b519ee64f758991016b7f74c13112b1c55cb8d4fc6a5f21de379e6'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Deja muchas tareas y trabajos en grupo pero se hacen fácil. En clase a veces es interesante y se abren buenos debates pero cuando toca exposiciones de los grupos la temática se vuelve demasiado aburrida y repetitiva. En fin, me pareció buena opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, '7f0aa2d909bc50c07a95afef986654b33ea81cc16e7282e98b00b10f3f56cbb1'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es aburrido, la secuela de intro al bostezo pero recargada. El profe no es mala persona, la informacion es interesante, pero la clase es muy repetitiva.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '3cb0c6654cb2b9f0e2df739059f16c6bbb6db416c09aa5a2743f4c16a9915326'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'El profe es pura vida y es muy fácil pasarle. Deja muchos trabajos en grupo pero son muy fáciles. Se hacen muchas presentaciones pero igualmente, son faciles. Es estricto con la asistencia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '1ecc4fc3b2654c06ca87b36e92c94e918b856876cf45fba8972bb58d98dbff2e'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Demasiado buen profe. Uno aprende un montón, se tocan temas polémicos. Hay muchos trabajillos en el curso, pero bastante fáciles. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1e02c1ad8a3f14df66ce8e9d8600c3e72cc0bf071359af927580e302595b22ba'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'El mejor porfe super recomendado, las clases son muy entretenidas e interesantes, se aprende mucho el curso no tiene examenes tiene un proyecto de investigacion muy sencillo , deja pocos trabajos y todos se pueden hacer en parejas, a veces pasa lista'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'a90091609523ec355c9fa60179156cb1551e96a0f9582ba65166d79111b8c29f'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'El profe es buena gente. Hace que el curso sea sencillo. El curso es básicamente ir a clase, ver películas, hacer informes cortos, una investigación y un foro. No es difícil. Pero claro, habrá gente que por hacer el papel se van a quedar, y son los que luego se quejan.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-07T00:00:00+00:00'::TIMESTAMPTZ, '8858564531f0244674e8b5b594f018571cec6b36b0d617cdb486b7e3400472bd'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Clase muy interesante, buena discusión, muchos temas importantes para el ejercicio profesional y para reflexionar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2018-11-07T00:00:00+00:00'::TIMESTAMPTZ, '85403145c8b0986bf27fb5f7a112b71a34a0e4d488bc9bdbac816a97cf475814'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Hay que hacer bastantes presentaciones durante el semestre pero a el le gusta comentar o que los compañeros comenten entonces exponer es muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'eeca4958427b483c1e18003c92b96238cd6321be3248860410cc11c866d24574'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es una exelente persona, deja muchos trabajos pero nada del otro mundo, sabe mucho y las clases son interesantes'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-12T00:00:00+00:00'::TIMESTAMPTZ, '0b72944335df1e8695273c553bc91a1cb6ed35f597fdc3d0e272150c30032fa1'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Es un buen profe, le da chanse de entregar los trabajos después , preparece para hacer como 20 ensayos, y habla ik poco de paja, y a veces es inevitable dormirse.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2fbd3ac5eff51c6bad5d59285db72d7af36830277d2af1d595289c55ceb50d8b'::TEXT, ARRAY[559]::BIGINT[]),
    (128::BIGINT, 'Deja bastantes trabajos pero fáciles y habla mucha paja'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e28fffce32df767f3e12b3876645dc4b5cd4904ac7e02f46f6e11d15815e0cee'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es estricto con la asistencia. Es moderadamente respetuoso. Habla un poco de paja pero se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e91e52cd4ce9762c7b9ad0415079a5de79c7ea3b6e762fe7e1c48f71cd775d24'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Excelente profesor y persona. Super recomendado. No sobrecarga el curso con muchas trabajos y se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c3118fe538c992710e8a9c28a02f4f7e872bfdc318488bf8d9f74b6660a54f9d'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Un curso muy fácil, simplemente hacer las lecturas para las presentaciones al igual que ponerle al proyecto. Ayuda mucho y si se le pide chance él lo da. Recomendado, le gusta que participen en clases para debatir o expandir el conocimiento pero no lo obliga por lo que lo hace un curso ameno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'cf73e7ac8b5e0fd987d87e11e6f39dff7d1374adc6ef41044f47d0951ef695db'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '13c6b34bd95cf9f516f9218d05a2e505d79011052081a555da975f766b191700'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Toma en cuenta la participación, se preocupa de que uno como estudiante saque algo del curso, es muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ba485c6529f3e0d708883379b95d6be486d5875b3488fed7ecb1a038591022a2'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'El profe buena nota y el curso es fácil'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'e93f26f99c8a59f9389ad850aeafa7307acdba3186d57aac61dc472dfa1fc2ad'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'El curso lo hace un poco pesado para dos créditos, pero en general es bastante bueno. Se aprende y la clase es llevadera. Como persona es buena gente, y como profesor se preocupa de que uno saque alguna utilidad del curso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1c29e387090c9ed6ca48966e63ff425f3c84c615390dc2f3797a27833c020401'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Todo el curso se trata de leer para discutir en clase. El problema es que sus autores favoritos son aburridísimos. La clase no sirve de nada y la asistencia es obligatoria. Lo bueno es que todo es grupal. Traigan amigos. La ética merece más.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9c8c50d93841c2660547f2d04caedb3e092d52f1cc74fb030555313cf72306b4'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Es cierto que deja muchos trabajos pero no quitan mucho tiempo, califica suave y explica bastante claro, además se sale temprano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'b8cc3251f5211918d3a1181a3afb9abc7581f8a9b553e760748c7cef03fbbf56'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Por desgracia este semestre cambió y dejó MUCHOS trabajos. Es muy bueno, muy respetuoso ( sus comentarios sobre Religión debería reservárselos ) pero es Pura Vida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2016-12-11T00:00:00+00:00'::TIMESTAMPTZ, '96ea2edb94471c63a10d0ff9b93390cadb8aa78b5d385b5d60d3f5c9c3918df9'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Deja muchos bretes, no es la mejor opción.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f41f01388f0a4d5414fe3fd93ddfcf8b1e4a515a5df867d79e2d5f188fa14cf8'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'No lo recomiendo porque sea malo sino porque deja demasiados trabajos para un curso de 2 creditos, quitan mucho tiempo, si pueden matriculen con alguien mas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7b529b929887e431ca4d6a30681b5be9ec20ea35cbd9339a3380010b6ec97f4c'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, '¡Excelente opción! Muy buena gente, comprensivo y las clases son chivas. No recarga al estudiante. Se aprende en serio de filosofía. ¡Recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7e837e1b6b2be471e357d79711bf098db0e9358ded94cf6b3af9024dfe4ffbc1'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Las clases son entretenidas. El profe se interesa mucho por dejar claro la materia. Pocos trabajos. Siempre atento.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7c2fcda9d13a447acb456a98d110731610fcee88588c5b95a14b63025da7e48d'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '10ba7ff3c164817c792212c44ef3707b7edc7d6427eb2c51ab4a09324870578f'::TEXT, ARRAY[628]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '848f63aee8650e9ff7f0f1f37768519e4ec583624cf26a3e14416e7de5bf828d'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Buen profe, no deja tantos trabajos y los que deja son fáciles por lo general en parejas, las clases no son tan aburridas. Recomienda buenas películas y series !!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '7e6efd69a71f1fea0cc9dd45f020a04cfc9867480c59f191587c6776a143d884'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'exc profe... clase didactica! no es muy magistral'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-21T00:00:00+00:00'::TIMESTAMPTZ, '444c17b0749f4e3b9decb48e7cb297eef26e3e62efe04331b29313460f5fff4f'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Muy buen profe...es muy pura vida, califica lo justo pero no exige tantas horas extraclase como otros profes. Clases de discusión muy interesantes...'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-21T00:00:00+00:00'::TIMESTAMPTZ, '14544d55deea42890e46e3ae8d4241477f226057ecc987c64b66f19232be5a18'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'bdf8cafa1574b00329f7c34b4743ed409a1894e2bad4dc87bcc3fbb6eb450143'::TEXT, ARRAY[628]::BIGINT[]),
    (128::BIGINT, 'La oratoria del profe hace que las clases no sean tan aburridas. Sabe hacer llamativo el tema del curso y en ocasiones mezcla con anécdotas de él. Trabajos en clase sencillos y acordes a la materia. Proyecto fácil incluso haciéndolo al final.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'c0b2261f6bfcc7ff7a253ca742a107bc37cd6ce6ca05c7eaa825964dab8e4381'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Deja muchas lecturas y clases aburridas, pero en general es excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'bf917ced7cf65502430a868d72ba21dd40ddf49c431cb2c1011830ec4ada08c7'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Deja trabajos sencillos y un trabajo final, es estricto en los formatos pero nada que no se pueda hacer. No sé pierde tanto tiempo en el curso.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'e9777f4a15c02b8074aad3fe4bdd7947f8988ea3ce37c589acabfa0ddf2c9648'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b52579b66ba291671060124e4676f2d01bc982fe969fc19daa06a5b34e596913'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '86333bb85075f223df5a28996adae539ff5fe567b2d4a00fe6b50a30e53b98ab'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'buen profe!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '7bec8f369223cfe6979895ece631513bd2d233d83c2d1e0ddcad54a578a24d8b'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Profe muy pura vida, toca temas muy interesantes en las clases, profesor no recomendado para personas cristianas intolerantes, puede llegar a tocar fibra en el tema. Deja bastantes trabajos pero sencillos. Personalmente siento que si aprendí algo en el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-10T00:00:00+00:00'::TIMESTAMPTZ, '40608dc180c591644fb062359eea33faef777ad3093d2ae16f52df59ac3b318f'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Pone demasiados trabajos, pero fáciles, ñas clases suelen ser aburridas. Pero se puede pasar con muy buena nota si sigue las instrucciones al pie de la letra.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '5afb6b1f8f451f49fa3e555e39aa8cbc3542a9fbc45024be42d992465a631264'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Demasiados trabajos'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'c3991a2849178c7deeddffe1f9734ebe17fcff2b388915635378d4a0fdcf8151'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'Las clases son un poco aburridas, le gusta que los estudiantes participen constantemente en la clase, califica con rubricas y los trabajos que pone son fáciles y el profe es buena gente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'db1d512d2cbc067ffca0974c63fe31c0ef45ddc307414b64c26fb5be4dfd7595'::TEXT, ARRAY[981]::BIGINT[]),
    (128::BIGINT, 'No tiene rúbrica de evaluación, entonces baja puntos según sienta la fé del estudiante (juega de ateo), poco o nulo contenido de aprendizaje, pero el curso se pasa luego de bostezos/dormir todo el semestre...'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3a8d0077f0d6a4204ad776bed5917d7a5ad53bece35470552c20985ca6f7d886'::TEXT, ARRAY[980, 981]::BIGINT[]),
    (128::BIGINT, 'Excelente profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '0596ba733872b1a5ae9f792510edab5be0801b413c70bab3995ed266a049195c'::TEXT, ARRAY[980]::BIGINT[]),
    (128::BIGINT, 'Excelente profesor. Los trabajos son fáciles y no hace muy pesado el curso. Se aprende bastante . La clase puede ser aburrida, pero eso no es muy fácil de evitar en un seminario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '18466ce71e0b974efaaef727a8ca4e81854be6c68ac35293dda2beaf83f9e60d'::TEXT, ARRAY[981]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
